using System;
using System.Collections.Generic;
using System.IO;

namespace PowerShapeBridge {
 internal static class ReturnedRotationEvidenceTests {
  internal static int Run(){
   if(!File.Exists(Path.Combine(Program.Root,".returned-rotation-fixture")))throw new InvalidOperationException("Own isolated return fixture required; no CAD.");int n=0;Action<bool> check=ok=>{if(!ok)throw new Exception("Returned rotation evidence guard "+n);n++;};Action<Action> rejects=action=>{bool failed=false;try{action();}catch(Exception e){if(!(e is IOException||e is InvalidDataException||e is InvalidOperationException||e is ArgumentException))throw;failed=true;}check(failed);};
   string root=Path.Combine(Program.Root,"isolated-return"),id=Guid.NewGuid().ToString("N"),sha=new string('a',64);Directory.CreateDirectory(Path.Combine(root,"operations",id));string previous=null;var states=new[]{"prepared","execution_claimed","command_started","outcome_unknown"};
   for(int i=0;i<4;i++){var details=new Dictionary<string,object>();if(i==1){details["nativeRequestId"]=id;details["targetCount"]=1;}if(i==2)details["targetCount"]=1;if(i==3)details["commandCallsAttempted"]=1;previous=NativeJournal.Freeze(Path.Combine(root,"operations",id,i.ToString("D6")+".json"),new Dictionary<string,object>{{"schemaVersion",1},{"operationId",id},{"planSha256",sha},{"sequence",i},{"previousSha256",previous},{"state",states[i]},{"timestampUtc",DateTime.UtcNow.ToString("o")},{"details",details}});}
   string folder=Path.Combine(root,"rotationcommands",id);Directory.CreateDirectory(folder);var target=new Dictionary<string,object>{{"entityKey",new[]{40,5}},{"compositeId",800000005},{"beforeMeasurementSha256",new string('b',64)}};var plan=new Dictionary<string,object>{{"targets",new[]{target}},{"angleDegrees",-30},{"nativeAxis",new double[]{2,-3,4,1,2,3}}};var started=new Dictionary<string,object>{{"operationId",id},{"planSha256",sha},{"index",0},{"entityKey",target["entityKey"]},{"compositeId",target["compositeId"]},{"angleDegrees",-30},{"nativeAxis",plan["nativeAxis"]},{"beforeObservationSha256",new string('c',64)}};string startSha=NativeJournal.Freeze(Path.Combine(folder,"000000.started.json"),started);var returned=new Dictionary<string,object>{{"operationId",id},{"planSha256",sha},{"index",0},{"startedSha256",startSha},{"returnCode",1},{"timestampUtc",DateTime.UtcNow.ToString("o")}};string returnPath=Path.Combine(folder,"000000.returned.json");NativeJournal.Freeze(returnPath,returned);
   using(var p=new OwnedOperationPlans.Proofs()){var j=ReturnedRotationEvidence.Journal(root,id,sha,p);check(((System.Collections.IList)j["hashes"]).Count==4);var c=ReturnedRotationEvidence.Command(root,id,sha,plan,p);check(Equals(c["returnCode"],1));}
   foreach(object value in new object[]{0,-1,"1",null}){returned["returnCode"]=value;File.WriteAllText(returnPath,Program.Json.Serialize(returned));using(var p=new OwnedOperationPlans.Proofs())rejects(()=>ReturnedRotationEvidence.Command(root,id,sha,plan,p));}returned["returnCode"]=1;File.WriteAllText(returnPath,Program.Json.Serialize(returned));
   foreach(string key in new[]{"operationId","planSha256","startedSha256"}){object good=returned[key];returned[key]=new string('f',key=="operationId"?32:64);File.WriteAllText(returnPath,Program.Json.Serialize(returned));using(var p=new OwnedOperationPlans.Proofs())rejects(()=>ReturnedRotationEvidence.Command(root,id,sha,plan,p));returned[key]=good;}File.WriteAllText(returnPath,Program.Json.Serialize(returned));
   target["entityKey"]=new[]{20,5};using(var p=new OwnedOperationPlans.Proofs())rejects(()=>ReturnedRotationEvidence.Command(root,id,sha,plan,p));target["entityKey"]=new[]{40,5};plan["targets"]=new[]{target,target};using(var p=new OwnedOperationPlans.Proofs())rejects(()=>ReturnedRotationEvidence.Command(root,id,sha,plan,p));plan["targets"]=new[]{target};
   string summary=Path.Combine(folder,"summary.json");File.WriteAllText(summary,"{}");using(var p=new OwnedOperationPlans.Proofs())rejects(()=>ReturnedRotationEvidence.Command(root,id,sha,plan,p));File.Delete(summary);
   string marker=Path.Combine(root,"operations",id,"writer.lock");File.WriteAllText(marker,"");using(var p=new OwnedOperationPlans.Proofs())rejects(()=>ReturnedRotationEvidence.Journal(root,id,sha,p));File.Delete(marker);
   string extra=Path.Combine(root,"operations",id,"000004.json");File.WriteAllText(extra,"{}");using(var p=new OwnedOperationPlans.Proofs())rejects(()=>ReturnedRotationEvidence.Journal(root,id,sha,p));File.Delete(extra);
   string last=Path.Combine(root,"operations",id,"000003.json");var changed=Program.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(last));changed["previousSha256"]=new string('d',64);File.WriteAllText(last,Program.Json.Serialize(changed));using(var p=new OwnedOperationPlans.Proofs())rejects(()=>ReturnedRotationEvidence.Journal(root,id,sha,p));
   DateTime now=DateTime.UtcNow;OwnedRotationExecution.RequirePostReadBudget(now.AddSeconds(90),now);check(true);rejects(()=>OwnedRotationExecution.RequirePostReadBudget(now.AddSeconds(89),now));rejects(()=>OwnedRotationExecution.RequirePostReadBudget(now,now));
   return n;
  }
 }
